$bmp = New-Object System.Drawing.Bitmap("$env:TEMP\bug6315-bg.png")
function Measure-Row($y1,$y2,$name) {
  $cols = @()
  for ($x=0; $x -lt $bmp.Width; $x++) {
    $dark=$false
    for ($y=$y1; $y -le $y2; $y++) { $p=$bmp.GetPixel($x,$y); if ($p.R -lt 120 -and $p.G -lt 120 -and $p.B -lt 120) { $dark=$true; break } }
    if ($dark) { $cols += $x }
  }
  # group into segments with gap>15px
  $segs=@(); if ($cols.Count -gt 0) { $start=$cols[0]; $prev=$cols[0]; for ($i=1;$i -lt $cols.Count;$i++){ if ($cols[$i]-$prev -gt 15){ $segs+=,@($start,$prev); $start=$cols[$i] }; $prev=$cols[$i] }; $segs+=,@($start,$prev) }
  Write-Output "$name : " + (($segs | ForEach-Object { "$($_[0])-$($_[1])" }) -join '  ')
}
